(() => {
    "use strict";
    const M=window.ZZXCyberChefModules,config=window.ZZX.CYBERCHEF,Storage=M.Storage;
    function boot(){const source=document.getElementById(config.sourceId),stored=Storage.read(config.storageKeys.source,config.defaultSource),initialMode=stored==="native"?"native":"modified";if(source)source.value=initialMode;document.getElementById(config.loadButtonId)?.addEventListener("click",()=>M.Runtime.load(M.Runtime.selectedMode(),{force:true}));document.getElementById(config.refreshButtonId)?.addEventListener("click",()=>M.Runtime.reload());source?.addEventListener("change",()=>M.Runtime.load(M.Runtime.selectedMode(),{force:true}));M.Resize?.boot();M.PageModes?.boot();M.History?.boot();M.Modifications?.boot();M.Macros?.boot();M.Parameters?.boot();M.Rotary?.boot();M.Downloads?.boot();M.Manifest?.load();M.Runtime.load(initialMode,{force:true});window.ZZXCyberChef={load:(...args)=>M.Runtime.load(...args),reload:()=>M.Runtime.reload(),loadRecipe:r=>M.Runtime.loadRecipe(r),getFrame:()=>M.Runtime.frame(),getDocument:()=>M.Runtime.document(),getWindow:()=>M.Runtime.window(),getMode:()=>M.Runtime.mode(),reapplyShim:()=>M.Runtime.reapply(),modules:M};}
    if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",boot,{once:true});else boot();
})();
